import hashlib
import os

def get_file_hash(filepath):
    hasher = hashlib.md5()
    try:
        with open(filepath, 'rb') as f:
            while True:
                data = f.read(8192)
                if not data:
                    break
                hasher.update(data)
        return hasher.hexdigest()
    except Exception:
        return None

base_dir = 'dosyalar'
hashes = {}

for root, dirs, files in os.walk(base_dir):
    for file in files:
        full_path = os.path.join(root, file)
        file_hash = get_file_hash(full_path)
        if file_hash is not None:
            # Get relative path with forward slashes
            rel_path = os.path.relpath(full_path, base_dir).replace(os.sep, '/')
            if file_hash not in hashes:
                hashes[file_hash] = []
            hashes[file_hash].append(rel_path)

duplicate_groups = [sorted(paths) for paths in hashes.values() if len(paths) > 1]
# Sort groups by the first path in each group
duplicate_groups.sort()

with open('kopyalar.txt', 'w', encoding='utf-8') as f:
    for group in duplicate_groups:
        f.write(" | ".join(group) + "\n")

print(f"Bulunan grup sayısı: {len(duplicate_groups)}")

