import hashlib
import os

def get_file_hash(filepath):
    hasher = hashlib.md5()
    try:
        with open(filepath, 'rb') as f:
            while True:
                data = f.read(65536)  # 64KB buffer
                if not data:
                    break
                hasher.update(data)
        return hasher.hexdigest()
    except Exception:
        return None

def find_duplicates(base_dir):
    if not os.path.exists(base_dir):
        return []

    hashes = {}
    for root, dirs, files in os.walk(base_dir):
        for file in files:
            full_path = os.path.join(root, file)
            file_hash = get_file_hash(full_path)
            if file_hash is not None:
                rel_path = os.path.relpath(full_path, base_dir).replace(os.sep, '/')
                if file_hash not in hashes:
                    hashes[file_hash] = []
                hashes[file_hash].append(rel_path)

    duplicate_groups = []
    for h in hashes:
        if len(hashes[h]) >= 2:
            duplicate_groups.append(sorted(hashes[h]))

    duplicate_groups.sort()
    return duplicate_groups

def main():
    base_dir = 'dosyalar'
    duplicate_groups = find_duplicates(base_dir)
    output_file = 'kopyalar.txt'

    with open(output_file, 'w', encoding='utf-8') as f:
        for group in duplicate_groups:
            f.write(" | ".join(group) + "\n")

    return len(duplicate_groups)

if __name__ == "__main__":
    count = main()
    print(f"Found {count} groups.")

